class ChitchatMatchResult {
  const ChitchatMatchResult(this.subIntent, {this.extractedName});

  final String subIntent;
  final String? extractedName;
}

class ChitchatMatcher {
  const ChitchatMatcher._();

  static bool _matchesRule(List<String> nonFillers, ChitchatRuleData rule) {
    if (nonFillers.isEmpty || nonFillers.length > rule.maxTokens) return false;
    if (rule.closed.isNotEmpty) {
      for (final t in nonFillers) {
        if (!rule.closed.contains(t)) return false;
      }
    }
    for (final group in rule.groups) {
      var found = false;
      for (final word in group) {
        if (nonFillers.contains(word)) {
          found = true;
          break;
        }
      }
      if (!found) return false;
    }
    return true;
  }

  static String? _extractNameAfter(List<String> tokens, int triggerIndex) {
    var i = triggerIndex + 1;
    while (i < tokens.length && ChitchatLexicon.skipAfterTrigger.contains(tokens[i])) {
      i++;
    }
    if (i >= tokens.length) return null;

    final nameTokens = <String>[];
    while (i < tokens.length && nameTokens.length < 2) {
      final tok = tokens[i];
      if (ChitchatLexicon.nameStops.contains(tok) ||
          ChitchatLexicon.fillers.contains(tok) ||
          ChitchatLexicon.declineWords.contains(tok)) {
        break;
      }
      if (ChitchatLexicon.hardNotNames.contains(tok)) return null;
      if (nameTokens.isEmpty && ChitchatLexicon.bareNotNames.contains(tok)) return null;
      nameTokens.add(tok);
      i++;
    }
    if (nameTokens.isEmpty) return null;
    return nameTokens.join(' ');
  }

  /// Matches normalized Arabic text against ChitchatLexicon social & name rules.
  static ChitchatMatchResult? match(String normQuery) {
    if (normQuery.isEmpty) return null;
    final tokens = normQuery.split(RegExp(r'\s+')).where((t) => t.isNotEmpty).toList();
    if (tokens.isEmpty) return null;

    final nonFillers = tokens.where((t) => !ChitchatLexicon.fillers.contains(t)).toList();

    // 0. Capabilities / Identity / OfflineInfo can mention "المحل" or "الشغل"
    //    (e.g. "بتعرف تعمل اي في المحل") as long as it's not a specific ERP query.
    final hasSpecificBusinessToken = tokens.any(
      (t) =>
          ChitchatLexicon.business.contains(t) &&
          t != 'المحل' &&
          t != 'محل' &&
          t != 'الشغل' &&
          t != 'شغل',
    );
    if (!hasSpecificBusinessToken) {
      final nonPrepositionTokens =
          nonFillers.where((t) => t != 'في' && t != 'عن').toList();
      for (final rule in ChitchatLexicon.socialRules) {
        if (rule.intent == 'capabilities' ||
            rule.intent == 'identity' ||
            rule.intent == 'offlineInfo') {
          if (_matchesRule(nonFillers, rule) ||
              _matchesRule(nonPrepositionTokens, rule)) {
            return ChitchatMatchResult(rule.intent);
          }
          // Also allow trailing "المحل" / "الشغل" (e.g. "بتعرف تعمل اي في المحل")
          final withoutStoreContext = nonPrepositionTokens
              .where((t) => t != 'المحل' && t != 'محل' && t != 'الشغل' && t != 'شغل')
              .toList();
          if (_matchesRule(withoutStoreContext, rule)) {
            return ChitchatMatchResult(rule.intent);
          }
        }
      }
    }

    // Business guard: never intercept ERP/business queries as greetings/howAreYou.
    for (final t in tokens) {
      if (ChitchatLexicon.business.contains(t)) return null;
    }

    // 1. Name rules (forgetName, changeName, askMyName)
    for (final rule in ChitchatLexicon.nameRules) {
      if (_matchesRule(nonFillers, rule)) {
        String? newName;
        if (rule.intent == 'changeName') {
          final idx = tokens.indexOf('اسمي');
          if (idx >= 0) {
            newName = _extractNameAfter(tokens, idx);
          }
        }
        return ChitchatMatchResult(rule.intent, extractedName: newName);
      }
    }

    // 2. Explicit name introduction (e.g. "اسمي احمد", "ناديني كريم")
    for (var i = 0; i < tokens.length; i++) {
      if (ChitchatLexicon.nameTriggers.contains(tokens[i])) {
        final name = _extractNameAfter(tokens, i);
        if (name != null) {
          return ChitchatMatchResult('setName', extractedName: name);
        }
      }
    }

    // 3. Social chitchat rules
    if (nonFillers.isEmpty && tokens.isNotEmpty) {
      return const ChitchatMatchResult('vocative');
    }
    for (final rule in ChitchatLexicon.socialRules) {
      if (_matchesRule(nonFillers, rule)) {
        return ChitchatMatchResult(rule.intent);
      }
    }

    return null;
  }
}

